mapper.select:
select id, order_no, schedule_date, tgf.mix_area, glue, tgf.machine_code,tmm.MACHINE_NAME, (ifnull(mid_finish_qty, 0) + ifnull(night_finish_qty, 0) + ifnull(day_finish_qty, 0)) as total_finish_qty, mid_finish_qty, night_finish_qty, day_finish_qty, remark, del_flag, create_by, create_time, update_by, update_time from t_glue_finish tgf left join( select machine_name, mix_area, machine_code from t_mix_machine where del_flag = '0' )tmm on tmm.MIX_AREA = tgf.MIX_AREA and tmm.MACHINE_CODE = tgf.MACHINE_CODE where tgf.del_flag = '0' and INSTR(order_no,#{orderNo})> 0 and schedule_date = #{scheduleDate} and tgf.mix_area = #{mixArea} and INSTR(glue, #{glue}) > 0
order by schedule_date desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber} row_numbers, #{data.orderNo,jdbcType= VARCHAR} order_no
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from T_GLUE_FINISH m inner join temp_table t on m.order_no = t.order_no and m.del_flag ='0'

mapper.insert:
insert into t_glue_finish (id,order_no,schedule_date,mix_area,glue,machine_code,mid_finish_qty,night_finish_qty,day_finish_qty,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{glueFinish.orderNo,jdbcType= VARCHAR} order_no, #{glueFinish.scheduleDate,jdbcType=TIMESTAMP} schedule_date, #{glueFinish.mixArea,jdbcType= VARCHAR} mix_area, #{glueFinish.glue,jdbcType= VARCHAR} glue, #{glueFinish.machineCode,jdbcType= VARCHAR} machine_code, #{glueFinish.midFinishQty,jdbcType=DOUBLE} mid_finish_qty, #{glueFinish.nightFinishQty,jdbcType=DOUBLE} night_finish_qty, #{glueFinish.dayFinishQty,jdbcType=DOUBLE} day_finish_qty, #{glueFinish.remark,jdbcType= VARCHAR} remark, #{glueFinish.delFlag,jdbcType= VARCHAR} del_flag, #{glueFinish.createBy,jdbcType= VARCHAR} create_by, #{glueFinish.createTime,jdbcType=TIMESTAMP} create_time, #{glueFinish.updateBy,jdbcType= VARCHAR} update_by, #{glueFinish.updateTime,jdbcType=TIMESTAMP} update_time from dual
) x
